#include <iostream>
#include <string>

// Minimal demonstration of contiguous vs linked layout concepts
struct SimpleNode {
    int data;
    SimpleNode* next;
    explicit SimpleNode(int val) : data(val), next(nullptr) {}
};

int main() {
    // Dynamic chain: 2 -> 1 -> 3
    SimpleNode* head = new SimpleNode(2);
    head->next = new SimpleNode(1);
    head->next->next = new SimpleNode(3);

    std::cout << "Traversing linked nodes: ";
    SimpleNode* current = head;
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->next;
    }
    std::cout << "\n";

    // Clean up heap allocations
    while (head != nullptr) {
        SimpleNode* temp = head;
        head = head->next;
        delete temp;
    }
    std::cout << "All nodes destroyed\n";
    return 0;
}

#include <iostream>
#include <string>

template<typename T>
class List;

template<typename NODETYPE>
class ListNode {
    friend class List<NODETYPE>;
public:
    explicit ListNode(const NODETYPE& info) : data(info), nextPtr(nullptr) {}
    NODETYPE getData() const { return data; }
private:
    NODETYPE data;
    ListNode<NODETYPE>* nextPtr;
};

template<typename NODETYPE>
class List {
public:
    List() : firstPtr(nullptr), lastPtr(nullptr) {}
    ~List() {
        ListNode<NODETYPE>* current = firstPtr;
        while (current != nullptr) {
            ListNode<NODETYPE>* temp = current;
            current = current->nextPtr;
            delete temp;
        }
    }

    bool isEmpty() const { return firstPtr == nullptr; }

    void insertAtFront(const NODETYPE& val) {
        auto* newPtr = new ListNode<NODETYPE>(val);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            newPtr->nextPtr = firstPtr;
            firstPtr = newPtr;
        }
    }

    void insertAtBack(const NODETYPE& val) {
        auto* newPtr = new ListNode<NODETYPE>(val);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            lastPtr->nextPtr = newPtr;
            lastPtr = newPtr;
        }
    }

    bool removeFromFront(NODETYPE& val) {
        if (isEmpty()) return false;
        ListNode<NODETYPE>* temp = firstPtr;
        val = temp->data;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            firstPtr = firstPtr->nextPtr;
        }
        delete temp;
        return true;
    }

    bool removeFromBack(NODETYPE& val) {
        if (isEmpty()) return false;
        ListNode<NODETYPE>* temp = lastPtr;
        val = temp->data;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            ListNode<NODETYPE>* current = firstPtr;
            while (current->nextPtr != lastPtr) {
                current = current->nextPtr;
            }
            lastPtr = current;
            lastPtr->nextPtr = nullptr;
        }
        delete temp;
        return true;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n";
            return;
        }
        std::cout << "The list is: ";
        ListNode<NODETYPE>* current = firstPtr;
        while (current != nullptr) {
            std::cout << current->data << " ";
            current = current->nextPtr;
        }
        std::cout << "\n";
    }

private:
    ListNode<NODETYPE>* firstPtr;
    ListNode<NODETYPE>* lastPtr;
};

template<typename T>
void runSequence(List<T>& listObj, const std::string& typeName) {
    std::cout << "Testing a List of " << typeName << " values\n";
    T val;
    listObj.insertAtFront(1);
    listObj.insertAtFront(2);
    listObj.insertAtBack(3);
    listObj.insertAtBack(4);
    listObj.print();

    if (listObj.removeFromFront(val))
        std::cout << val << " removed from list\n";
    listObj.print();

    if (listObj.removeFromBack(val))
        std::cout << val << " removed from list\n";
    listObj.print();
    std::cout << "End list test\n\n";
}

int main() {
    List<int> integerList;
    runSequence(integerList, "integer");
    return 0;
}
